#include "aero.h"
static bool graph_visit(int v,int n,bool edges[100][100],int color[100]){color[v]=1;for(int j=0;j<n;j++)if(edges[v][j]){if(color[j]==1)return true;if(color[j]==0&&graph_visit(j,n,edges,color))return true;}color[v]=2;return false;}
static bool safety(int n,int m,int a[100][6],int need[100][6],int *work,bool *finish,int *seq,int *length,bool output){
 bool progress=true;*length=0;if(output)printf("[");bool comma=false;
 while(progress){progress=false;for(int i=0;i<n;i++)if(!finish[i]){bool fit=true;for(int r=0;r<m;r++)if(need[i][r]>work[r])fit=false;if(fit){
  if(output){if(comma)putchar(',');comma=true;printf("{\"process\":%d,\"work_before\":[",i);for(int r=0;r<m;r++)printf("%s%d",r?",":"",work[r]);printf("],\"need\":[");for(int r=0;r<m;r++)printf("%s%d",r?",":"",need[i][r]);printf("],\"work_after\":[");}
  for(int r=0;r<m;r++){work[r]+=a[i][r];if(output)printf("%s%d",r?",":"",work[r]);}if(output)printf("]}");finish[i]=true;seq[(*length)++]=i;progress=true;
 }}}
 if(output)printf("]");for(int i=0;i<n;i++)if(!finish[i])return false;return true;
}
void banker(int root,bool detection){int av=field(root,"available"),al=field(root,"allocation"),ma=field(root,detection?"request":"maximum"),n=tok[al].size,m=tok[av].size;
 if(n<1||n>100||m<1||m>6||tok[ma].size!=n)fail("Matrices require 1..100 processes and 1..6 resources");
 int a[100][6]={{0}},need[100][6]={{0}},available[6]={0},work[6],seq[100],len=0;bool finish[100]={false};
 for(int r=0;r<m;r++){available[r]=number(item(av,r),-1);if(available[r]<0||available[r]>10000)fail("Invalid available vector");}
 for(int i=0;i<n;i++){if(tok[item(al,i)].size!=m||tok[item(ma,i)].size!=m)fail("Matrix shape mismatch");bool owns=false;for(int r=0;r<m;r++){a[i][r]=number(item(item(al,i),r),-1);int max=number(item(item(ma,i),r),-1);if(a[i][r]<0||max<0||max>10000||a[i][r]>10000||(!detection&&a[i][r]>max))fail("Invalid allocation or maximum");need[i][r]=detection?max:max-a[i][r];if(a[i][r])owns=true;}if(detection&&!owns)finish[i]=true;}
 bool granted=false;char reason[160]="Safety analysis only";int requested=field(root,"request_process");
 if(!detection&&requested){int i=number(requested,-1),req=field(root,"request_vector");if(i<0||i>=n||tok[req].size!=m)fail("Invalid request process or vector");bool valid=true;for(int r=0;r<m;r++){int x=number(item(req,r),-1);if(x<0)fail("Negative request");if(x>need[i][r]||x>available[r])valid=false;}
  if(valid){for(int r=0;r<m;r++){int x=number(item(req,r),0);available[r]-=x;a[i][r]+=x;need[i][r]-=x;}memcpy(work,available,sizeof(work));bool f[100]={false};int l;bool safe=safety(n,m,a,need,work,f,seq,&l,false);
   if(safe||!flag(root,"safe_mode",true)){granted=true;snprintf(reason,sizeof(reason),safe?"Granted: resulting state is safe":"Granted in normal mode: state is unsafe, not necessarily deadlocked");}
   else{for(int r=0;r<m;r++){int x=number(item(req,r),0);available[r]+=x;a[i][r]-=x;need[i][r]+=x;}snprintf(reason,sizeof(reason),"Rejected and rolled back: tentative state is unsafe");}
  }else snprintf(reason,sizeof(reason),"Rejected: request exceeds remaining claim or available resources");
 }
 memcpy(work,available,sizeof(work));printf("{\"steps\":");bool safe=safety(n,m,a,need,work,finish,seq,&len,true);printf(",\"safe\":%s,\"deadlocked\":%s,\"granted\":%s,\"reason\":",safe?"true":"false",detection&&!safe?"true":"false",granted?"true":"false");quote(reason);printf(",\"sequence\":[");for(int i=0;i<len;i++)printf("%s%d",i?",":"",seq[i]);printf("],\"affected\":[");bool c=false;for(int i=0;i<n;i++)if(!finish[i]){printf("%s%d",c?",":"",i);c=true;}printf("],\"need\":[");for(int i=0;i<n;i++){if(i)putchar(',');putchar('[');for(int r=0;r<m;r++)printf("%s%d",r?",":"",need[i][r]);putchar(']');}printf("],\"allocation\":[");for(int i=0;i<n;i++){if(i)putchar(',');putchar('[');for(int r=0;r<m;r++)printf("%s%d",r?",":"",a[i][r]);putchar(']');}printf("],\"available\":[");for(int r=0;r<m;r++)printf("%s%d",r?",":"",available[r]);printf("]");
 if(detection){bool edges[100][100]={{false}},hold=false;int colors[100]={0};for(int i=0;i<n;i++){bool owns=false,requests=false;for(int r=0;r<m;r++){owns|=a[i][r]>0;requests|=need[i][r]>0;}hold|=owns&&requests;}printf(",\"wait_for\":[");bool edge=false;for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(i!=j){bool depends=false;for(int r=0;r<m;r++)if(need[i][r]>available[r]&&a[j][r]>0)depends=true;if(depends){edges[i][j]=true;printf("%s[%d,%d]",edge?",":"",i,j);edge=true;}}bool cycle=false;for(int i=0;i<n;i++)if(!colors[i]&&graph_visit(i,n,edges,colors))cycle=true;printf("],\"conditions\":{\"mutual_exclusion\":true,\"hold_and_wait\":%s,\"no_preemption\":true,\"circular_wait\":%s}",hold?"true":"false",cycle?"true":"false");}
 if(detection&&flag(root,"recover",false)&&!safe){int victim=get(root,"victim",-1);if(victim<0){int lowest=INT_MAX;for(int i=0;i<n;i++)if(!finish[i]){int cost=0;for(int r=0;r<m;r++)cost+=a[i][r];if(cost<lowest){lowest=cost;victim=i;}}}if(victim<0||victim>=n)fail("Invalid victim");
  for(int r=0;r<m;r++){available[r]+=a[victim][r];a[victim][r]=0;need[victim][r]=0;}memset(finish,0,sizeof(finish));for(int i=0;i<n;i++){bool owns=false;for(int r=0;r<m;r++)if(a[i][r])owns=true;if(!owns)finish[i]=true;}finish[victim]=true;memcpy(work,available,sizeof(work));bool restored=safety(n,m,a,need,work,finish,seq,&len,false);printf(",\"recovery\":{\"victim\":%d,\"restored\":%s,\"available_after\":[",victim,restored?"true":"false");for(int r=0;r<m;r++)printf("%s%d",r?",":"",available[r]);printf("],\"allocation_after\":[");for(int i=0;i<n;i++){if(i)putchar(',');putchar('[');for(int r=0;r<m;r++)printf("%s%d",r?",":"",a[i][r]);putchar(']');}printf("],\"request_after\":[");for(int i=0;i<n;i++){if(i)putchar(',');putchar('[');for(int r=0;r<m;r++)printf("%s%d",r?",":"",need[i][r]);putchar(']');}printf("],\"remaining\":[");c=false;for(int i=0;i<n;i++)if(!finish[i]){printf("%s%d",c?",":"",i);c=true;}printf("]}");
 }puts("}");
}
